package ge.opensoft.openservice;
import static ge.opensoft.openservice.Values.*;
import static ge.opensoft.openservice.TypedFields.require;
import java.sql.SQLException;
import java.util.*;
import org.apache.commons.codec.digest.DigestUtils;
/** Explicit public replies; current recipient eligibility is checked again by the delivery worker. */
final class CustomerReplies {
 private CustomerReplies() {}
 static Map<String,Object> record(Store.Db db,String id)throws SQLException{var item=Service.readRecord(db,"customer_case",id);if(!FieldAccess.allowed(db,Service.schema(db,"customer_case"),"description"))throw new Failure(403,"Customer reply access requires case description access");return item;}
 static Map<String,Object> preference(Store.Db db)throws SQLException{
  if(!"requester".equals(db.viewerRole))throw new Failure(403,"Customer requester access required");var row=db.one("SELECT enabled,revision FROM os_customer_delivery WHERE user_id=?",db.viewerId);if(row==null)row=map("enabled",0,"revision",0);var user=db.one("SELECT email_verified FROM os_user WHERE user_id=?",db.viewerId);row.put("verified_email",((Number)user.get("email_verified")).intValue()==1);return row;
 }
 static Map<String,Object> preference(Store.Db db,Object input)throws SQLException{if(db.postgres)db.all("SELECT pg_advisory_xact_lock(18439,4)");var current=preference(db);var body=object(input);require(body.keySet().equals(Set.of("revision","enabled")),"Provide notification revision and enabled");ProblemInvestigations.revision(body.get("revision"),current.get("revision"));require(body.get("enabled") instanceof Boolean,"Choose enabled or disabled");db.update("INSERT INTO os_customer_delivery(user_id,enabled,revision) VALUES(?,?,?) ON CONFLICT(user_id) DO UPDATE SET enabled=excluded.enabled,revision=excluded.revision",db.viewerId,(Boolean)body.get("enabled")?1:0,((Number)current.get("revision")).intValue()+1);SecurityEvents.record(db,db.viewerId,db.viewerId,"customer.email_preference",map("enabled",body.get("enabled")));return preference(db);}
 static Map<String,Object> recipient(Store.Db db,String id)throws SQLException{
  var user=db.one("SELECT u.user_id,u.email FROM os_customer_case c JOIN os_user u ON u.user_id=c.user_id JOIN os_customer_delivery p ON p.user_id=u.user_id WHERE c.record_id=? AND u.active=1 AND u.role='requester' AND u.password_reset_required=0 AND u.email_verified=1 AND p.enabled=1",id);if(user==null)return null;String viewer=db.viewerId,role=db.viewerRole;try{db.viewerId=user.get("user_id").toString();db.viewerRole="requester";record(db,id);return user;}catch(Failure hidden){return null;}finally{db.viewerId=viewer;db.viewerRole=role;}
 }
 static boolean writable(Store.Db db)throws SQLException{var rule=object(TypedFields.rules(Service.schema(db,"customer_case")).getOrDefault("description",map()));return !rule.containsKey("write_roles") || ((List<?>)rule.get("write_roles")).contains(db.viewerRole);}
 static Map<String,Object> page(Store store,Store.Db db,String id)throws SQLException{
  var item=record(db,id);var rows=db.all("SELECT r.reply_id,r.actor_name,r.body,r.created,CASE WHEN r.job_id='' THEN 'portal' ELSE COALESCE(o.state,'unavailable') END AS delivery,COALESCE(o.attempts,0) AS attempts FROM os_customer_reply r LEFT JOIN os_outbox o ON o.job_id=r.job_id WHERE r.record_id=? ORDER BY r.ordinal",id);return map("record",FieldAccess.serialize(db,item),"replies",rows,"can_publish",Set.of("admin","agent").contains(db.viewerRole) && RecordPolicy.allows(Service.schema(db,"customer_case"),"update",db.viewerRole) && writable(db),"can_email",store.environment.getProperty("DELIVERY_ENABLED",Boolean.class,false) && recipient(db,id)!=null);
 }
 static Map<String,Object> publish(Store store,Store.Db db,String id,Object input)throws Exception{
  if(!Set.of("admin","agent").contains(db.viewerRole))throw new Failure(403,"Support staff access required");if(db.postgres)db.all("SELECT pg_advisory_xact_lock(18439,4)");var item=record(db,id);RecordPolicy.require(Service.schema(db,"customer_case"),"update",db.viewerRole);if(!writable(db))throw new Failure(403,"Case description write access required");var body=object(input);require(body.keySet().equals(Set.of("record_revision","key","body","email")),"Provide reviewed record revision, key, public body and email choice");String text=WorkJobs.text(body.get("body"),4000),key=WorkJobs.text(body.get("key"),32);require(key.matches("[0-9a-f]{32}"),"Use a 32-character reply key");require(body.get("email") instanceof Boolean,"Choose portal only or email delivery");String fingerprint=DigestUtils.sha256Hex(JSON.writeValueAsString(new TreeMap<>(body)));var previous=db.one("SELECT fingerprint FROM os_customer_reply WHERE record_id=? AND actor_id=? AND submission_key=?",id,db.viewerId,key);if(previous!=null){if(!fingerprint.equals(previous.get("fingerprint")))throw new Failure(409,"Reply key already identifies different content");return page(store,db,id);}ProblemInvestigations.revision(body.get("record_revision"),item.get("revision"));long count=db.count("SELECT COUNT(*) FROM os_customer_reply WHERE record_id=?",id);require(count<200,"At most 200 published replies belong to one case");String reply=Values.id(),job="",actor=Service.account(db,db.viewerId).get("name").toString();
  if((Boolean)body.get("email")){if(!store.environment.getProperty("DELIVERY_ENABLED",Boolean.class,false))throw new Failure(409,"Email delivery is not enabled");SmtpDelivery.base(store.environment);var user=recipient(db,id);if(user==null)throw new Failure(409,"Customer email delivery is not currently available");job=Outbox.enqueue(db,store.secret,"email.customer_reply",reply,map("type","customer_reply","reply_id",reply,"email",user.get("email"),"path","/record/customer_case/"+id+"/replies","body",text),System.currentTimeMillis()+604800000L);}
  db.update("INSERT INTO os_customer_reply(reply_id,record_id,actor_id,actor_name,ordinal,body,created,submission_key,fingerprint,job_id) VALUES(?,?,?,?,?,?,?,?,?,?)",reply,id,db.viewerId,actor,count+1,text,now(),key,fingerprint,job);Service.update(db,"customer_case",item,map(),actor,db.viewerRole,body.get("record_revision").toString());Service.audit(db,item,actor,"customer.reply_published",map("reply_id",reply,"email",body.get("email")));return page(store,db,id);
 }
 static boolean valid(Store.Db db,Map<String,Object> payload)throws SQLException{
  var reply=db.one("SELECT record_id,body FROM os_customer_reply WHERE reply_id=?",payload.get("reply_id"));if(reply==null)return false;String id=reply.get("record_id").toString();var recipient=recipient(db,id);return recipient!=null && Objects.equals(recipient.get("email"),payload.get("email")) && Objects.equals(reply.get("body"),payload.get("body")) && Objects.equals("/record/customer_case/"+id+"/replies",payload.get("path")) && Objects.equals("customer_reply",payload.get("type"));
 }
}
